@st.cache_resource
def _ottieni_worksheet_tiratori():
    import gspread
    from google.oauth2.service_account import Credentials
    credenziali = Credentials.from_service_account_info(
        dict(st.secrets['gcp_service_account']), scopes=GOOGLE_SHEETS_SCOPES
    )
    client = gspread.authorize(credenziali)
    foglio = client.open_by_key(st.secrets['season_sheet_id'])
    try:
        worksheet = foglio.worksheet('ShooterSeasonData')
    except Exception:
        worksheet = foglio.add_worksheet(title='ShooterSeasonData', rows=2000, cols=50)
        worksheet.append_row(['nome', 'data', 'squadra', 'squadra_home', 'squadra_away', 'dati_json', 'neutro'])
    return _WorksheetConRetry(worksheet)

def _match_a_riga_sheet_tiratori(match):
    dati_json = match['dati'].to_json(orient='split', date_format='iso')
    chunk = _dividi_json_in_chunk(dati_json)
    return [match['nome'], str(match['data']), match['squadra'],
            match.get('squadra_home') or '', match.get('squadra_away') or '',
            str(bool(match.get('neutro', False))), json.dumps(match.get('campionati_esclusi', [])),
            str(bool(match.get('partita_completa', True))),
            str(len(chunk))] + chunk

def _riga_sheet_a_match_tiratori(riga):
    from datetime import datetime as _dt
    nome, data_str, squadra = riga[0], riga[1], riga[2]
    squadra_home = riga[3] if len(riga) > 3 and riga[3] else None
    squadra_away = riga[4] if len(riga) > 4 and riga[4] else None
    campionati_esclusi = []
    partita_completa = True
    # Stessa logica di _riga_sheet_a_match: un JSON vero non può mai valere letteralmente
    # 'True'/'False', e la lista campionati_esclusi (sempre '[...]') non può mai essere confusa
    # con un numero puro (num_chunk) — discriminatori sicuri per i quattro formati possibili.
    if len(riga) >= 6 and riga[5].strip() in ('True', 'False'):
        neutro = riga[5].strip() == 'True'
        if len(riga) >= 7 and riga[6].strip().startswith('['):
            try:
                campionati_esclusi = json.loads(riga[6])
            except Exception:
                campionati_esclusi = []
            if len(riga) >= 8 and riga[7].strip() in ('True', 'False'):
                partita_completa = riga[7].strip() == 'True'
                num_chunk = int(riga[8]) if len(riga) > 8 and riga[8].strip().isdigit() else 0
                dati_json = ''.join(riga[9:9 + num_chunk])
            else:
                num_chunk = int(riga[7]) if len(riga) > 7 and riga[7].strip().isdigit() else 0
                dati_json = ''.join(riga[8:8 + num_chunk])
        else:
            num_chunk = int(riga[6]) if len(riga) > 6 and riga[6].strip().isdigit() else 0
            dati_json = ''.join(riga[7:7 + num_chunk])
    else:
        dati_json = riga[5] if len(riga) > 5 else riga[3]
        neutro = riga[6].strip().lower() == 'true' if len(riga) > 6 else False
    df = pd.read_json(io.StringIO(dati_json), orient='split')
    if 'Is_Money_Time' in df.columns:
        df['Is_Money_Time'] = df['Is_Money_Time'].astype(bool)
    if 'TIRATORE_ID' not in df.columns and 'TIRATORE_CLEAN' in df.columns:
        df['TIRATORE_ID'] = df['TIRATORE_CLEAN'].apply(identita_giocatore)
    if 'macro_settore_tir' in df.columns and 'TIRO_CLEAN' in df.columns:
        df['macro_settore_tir'] = df['TIRO_CLEAN'].apply(mappa_macro_settore_tiratori)
    try:
        data_valore = _dt.strptime(data_str, '%Y-%m-%d').date()
    except Exception:
        data_valore = data_str
    return {'nome': nome, 'data': data_valore, 'squadra': squadra,
            'squadra_home': squadra_home, 'squadra_away': squadra_away, 'dati': df, 'neutro': neutro,
            'campionati_esclusi': campionati_esclusi, 'partita_completa': partita_completa}

def carica_stagione_tiratori_da_disco():
    if _google_sheets_configurato():
        try:
            worksheet = _ottieni_worksheet_tiratori()
            valori = worksheet.get_all_values()
            if len(valori) <= 1:
                # Stesso ragionamento di carica_stagione_da_disco: un foglio che sembra vuoto
                # potrebbe essere il risultato di un salvataggio interrotto a metà (cancellato
                # ma mai riscritto correttamente) — controllo prima un backup locale più ricco.
                if os.path.exists(SHOOTER_SEASON_FILE):
                    try:
                        with open(SHOOTER_SEASON_FILE, 'rb') as f:
                            db_backup = pickle.load(f)
                        if db_backup:
                            st.sidebar.error(
                                f"⚠️ Google Sheets shooter season looks EMPTY, but a local backup with "
                                f"{len(db_backup)} match(es) was found — using the backup instead. This "
                                f"usually means an earlier save was interrupted partway through. Please "
                                f"check Google Sheets' Version History on the 'ShooterSeasonData' tab to "
                                f"confirm and permanently restore the correct version there too."
                            )
                            for m in db_backup:
                                if 'TIRATORE_ID' not in m['dati'].columns and 'TIRATORE_CLEAN' in m['dati'].columns:
                                    m['dati']['TIRATORE_ID'] = m['dati']['TIRATORE_CLEAN'].apply(identita_giocatore)
                                if 'macro_settore_tir' in m['dati'].columns and 'TIRO_CLEAN' in m['dati'].columns:
                                    m['dati']['macro_settore_tir'] = m['dati']['TIRO_CLEAN'].apply(mappa_macro_settore_tiratori)
                            return db_backup
                    except Exception:
                        pass
                return []
            return [_riga_sheet_a_match_tiratori(riga) for riga in valori[1:] if riga and riga[0]]
        except Exception as e:
            st.sidebar.error(f"⚠️ Could not load shooter season from Google Sheets: {e}")
            # Non arrendersi al primo errore: prova comunque il backup locale sotto
            # (se esiste) prima di restituire [] vuoto — meglio mostrare dati
            # un po' vecchi che nessun dato affatto.
    if os.path.exists(SHOOTER_SEASON_FILE):
        try:
            with open(SHOOTER_SEASON_FILE, 'rb') as f:
                db = pickle.load(f)
            for m in db:
                if 'TIRATORE_ID' not in m['dati'].columns and 'TIRATORE_CLEAN' in m['dati'].columns:
                    m['dati']['TIRATORE_ID'] = m['dati']['TIRATORE_CLEAN'].apply(identita_giocatore)
                if 'macro_settore_tir' in m['dati'].columns and 'TIRO_CLEAN' in m['dati'].columns:
                    m['dati']['macro_settore_tir'] = m['dati']['TIRO_CLEAN'].apply(mappa_macro_settore_tiratori)
            return db
        except Exception:
            return []
    return []

def salva_stagione_tiratori_su_disco(db, permetti_svuotamento=False):
    # Backup locale SEMPRE scritto per primo, PRIMA di tentare Google Sheets — così un
    # salvataggio remoto interrotto a metà (rete, quota, qualunque motivo) non lascia MAI
    # l'app priva di una copia recente e recuperabile: è così che si sono persi i dati la
    # volta scorsa (il backup locale esisteva solo come fallback DOPO un errore, mai come
    # copia sistematica di ogni salvataggio riuscito).
    try:
        with open(SHOOTER_SEASON_FILE, 'wb') as _f_backup_preventivo:
            pickle.dump(db, _f_backup_preventivo)
    except Exception:
        pass
    intestazione_tiratori = ['nome', 'data', 'squadra', 'squadra_home', 'squadra_away', 'neutro', 'num_chunk']
    if _google_sheets_configurato():
        try:
            worksheet = _ottieni_worksheet_tiratori()
            righe = [_match_a_riga_sheet_tiratori(m) for m in db]
            for riga in righe:
                for cella in riga:
                    if len(str(cella)) > 49000:
                        raise ValueError(f"A cell still exceeds Google Sheets' limit ({len(str(cella))} chars) even after chunking — aborting before touching the sheet.")
            colonne_necessarie = max([len(r) for r in righe] + [len(intestazione_tiratori)])
            if worksheet.col_count < colonne_necessarie:
                worksheet.resize(cols=colonne_necessarie)
            _blocca_se_svuotamento_sospetto(worksheet, db, permetti_svuotamento, "shooter match(es)")
            worksheet.clear()
            worksheet.append_row(intestazione_tiratori)
            if righe:
                worksheet.append_rows(righe)
            return
        except Exception as e:
            st.sidebar.error(f"⚠️ Could not save shooter season to Google Sheets: {e}")
            if not db:
                # Dati vuoti e salvataggio remoto fallito: NON tocco il backup locale,
                # per non rischiare di sovrascrivere un backup buono con dati vuoti.
                return
    with open(SHOOTER_SEASON_FILE, 'wb') as f:
        pickle.dump(db, f)

