@st.cache_resource
def _ottieni_worksheet_training_pdf():
    import gspread
    from google.oauth2.service_account import Credentials
    credenziali = Credentials.from_service_account_info(
        dict(st.secrets['gcp_service_account']), scopes=GOOGLE_SHEETS_SCOPES
    )
    client = gspread.authorize(credenziali)
    foglio = client.open_by_key(st.secrets['season_sheet_id'])
    try:
        worksheet = foglio.worksheet('TrainingSessionsPDF')
        if worksheet.row_count < 20000:
            worksheet.resize(rows=20000)
    except Exception:
        worksheet = foglio.add_worksheet(title='TrainingSessionsPDF', rows=20000, cols=3)
        worksheet.append_row(['id', 'indice_chunk', 'chunk_base64'])
    # Un margine di retry leggermente più ampio del default per questo foglio (a rischio di
    # essere il più grande dell'app), ma SENZA esagerare: con 8 tentativi e base 2s il tempo di
    # attesa cumulativo poteva superare i 4 minuti per una singola operazione se un problema
    # temporaneo si ripeteva più volte — troppo per un'azione interattiva dove l'utente aspetta
    # attivamente. 4 tentativi/base 1.2s assorbono comunque un rate-limit passeggero (pochi
    # secondi) senza far percepire l'app come bloccata.
    return _WorksheetConRetry(worksheet, tentativi_massimi=4, attesa_iniziale=1.2)

def carica_sessioni_allenamento_da_disco():
    if _google_sheets_configurato():
        try:
            worksheet_meta = _ottieni_worksheet_training_meta()
            valori_meta = worksheet_meta.get_all_values()
            if len(valori_meta) <= 1:
                # Il foglio sembra vuoto: potrebbe essere un salvataggio interrotto a metà (il
                # foglio viene cancellato PRIMA di riscriverlo — se qualcosa va storto durante la
                # riscrittura, resta vuoto). Prima di accettarlo come verità, controllo se esiste
                # un backup locale più ricco — è così che si sono già persi altri dati in passato.
                if os.path.exists(TRAINING_SESSIONS_FILE):
                    try:
                        with open(TRAINING_SESSIONS_FILE, 'rb') as f:
                            backup = pickle.load(f)
                        if backup:
                            st.sidebar.error(
                                "⚠️ Google Sheets training sessions look EMPTY, but a local backup with "
                                f"{len(backup)} session(s) was found — using the backup instead. This "
                                "usually means an earlier save was interrupted partway through. Please "
                                "check Google Sheets' Version History on the 'TrainingSessionsMeta' and "
                                "'TrainingSessionsPDF' tabs to confirm and restore them there too."
                            )
                            return backup
                    except Exception:
                        pass
                return []
            worksheet_pdf = _ottieni_worksheet_training_pdf()
            valori_pdf = worksheet_pdf.get_all_values()
            chunk_per_id = {}
            for riga in valori_pdf[1:]:
                if not riga or not riga[0]:
                    continue
                chunk_per_id.setdefault(riga[0], []).append((int(riga[1]), riga[2]))
            sessioni = []
            for riga in valori_meta[1:]:
                if not riga or not riga[0]:
                    continue
                id_sessione, nome_sessione, dati_json = riga[0], riga[1], riga[2]
                dati = json.loads(dati_json)
                pdf_bytes = None
                if id_sessione in chunk_per_id:
                    chunk_ordinati = sorted(chunk_per_id[id_sessione], key=lambda c: c[0])
                    b64_completo = ''.join(c[1] for c in chunk_ordinati)
                    pdf_bytes = base64.b64decode(b64_completo)
                sessioni.append({
                    'id': id_sessione, 'nome_sessione': nome_sessione, 'pdf_bytes': pdf_bytes,
                    'link_list': dati.get('link_list', []), 'note_generali': dati.get('note_generali', ''),
                    'assegnazioni': dati.get('assegnazioni', []), 'gruppo': dati.get('gruppo'),
                })
            return sessioni
        except Exception as e:
            st.sidebar.error(f"⚠️ Could not load training sessions from Google Sheets: {e}")
            # Non arrendersi al primo errore: prova comunque il backup locale sotto
            # (se esiste) prima di restituire [] vuoto — meglio mostrare dati
            # un po' vecchi che nessun dato affatto.
    if os.path.exists(TRAINING_SESSIONS_FILE):
        try:
            with open(TRAINING_SESSIONS_FILE, 'rb') as f:
                return pickle.load(f)
        except Exception:
            return []
    return []

def aggiorna_metadati_singola_sessione(id_sessione, lista_sessioni_completa):
    """Salva le modifiche di UNA sola sessione — nome, gruppo, note, link video, assegnazioni —
    toccando SOLO il foglio dei metadati, senza mai sfiorare quello dei PDF (che può avere
    centinaia di righe pesanti dalle altre sessioni). La versione precedente richiamava sempre
    il salvataggio completo per QUALSIASI modifica, anche minima, riscrivendo ogni volta tutti i
    chunk PDF di tutte le sessioni anche quando il file non era affatto cambiato — questo era il
    vero motivo per cui aggiungere un link o assegnare una squadra sembrava lento quanto
    sostituire un intero file. Fa un fallback sicuro al salvataggio completo se qualcosa
    nell'aggiornamento mirato non torna."""
    # Backup locale SEMPRE aggiornato per primo, come in ogni altra funzione di salvataggio.
    try:
        with open(TRAINING_SESSIONS_FILE, 'wb') as _f_backup_preventivo:
            pickle.dump(lista_sessioni_completa, _f_backup_preventivo)
    except Exception:
        pass

    if not _google_sheets_configurato():
        return

    sessione_target = next((s for s in lista_sessioni_completa if s['id'] == id_sessione), None)
    if sessione_target is None:
        return

    try:
        worksheet_meta = _ottieni_worksheet_training_meta()
        dati_json_nuovi = json.dumps({
            'link_list': sessione_target['link_list'], 'note_generali': sessione_target['note_generali'],
            'assegnazioni': sessione_target['assegnazioni'], 'gruppo': sessione_target.get('gruppo'),
        })
        riga_nuova = [id_sessione, sessione_target['nome_sessione'], dati_json_nuovi]
        for cella in riga_nuova:
            if len(str(cella)) > 49000:
                raise ValueError(f"A cell still exceeds Google Sheets' limit ({len(str(cella))} chars).")

        # Leggo SOLO la colonna degli ID (leggera), non l'intero foglio, per trovare la riga da
        # aggiornare — stessa ottimizzazione già usata per il worksheet dei PDF.
        colonna_id_attuale = worksheet_meta.col_values(1)
        indici_riga = [i + 2 for i, id_riga in enumerate(colonna_id_attuale[1:]) if id_riga == id_sessione]

        if len(indici_riga) == 1:
            # Caso normale: una sola riga esistente per questo ID — la aggiorno sul posto con
            # 'update', senza toccare nessun'altra riga (a differenza di delete+append, un
            # singolo update in-place è ancora più leggero per una singola riga di metadati).
            worksheet_meta.update(f"A{indici_riga[0]}:C{indici_riga[0]}", [riga_nuova])
        elif not indici_riga:
            # Sessione non ancora presente sul foglio (es. appena creata): la aggiungo in fondo.
            worksheet_meta.append_row(riga_nuova)
        else:
            # Caso raro/inatteso (più righe per lo stesso ID): torno al salvataggio completo
            # sicuro invece di rischiare di lasciare righe duplicate o incoerenti.
            salva_sessioni_allenamento_su_disco(lista_sessioni_completa)
    except Exception as e:
        st.sidebar.error(f"⚠️ Could not update this session's details on Google Sheets: {e}")

def sostituisci_file_singola_sessione(id_sessione, nuovo_file_bytes, lista_sessioni_completa):
    """Sostituisce il PDF/immagine di UNA sola sessione, toccando solo le sue righe nel foglio
    Google Sheets — non l'intero foglio con tutte le altre sessioni. La versione precedente
    richiamava sempre il salvataggio completo (cancella-tutto-e-riscrivi-tutto), che con molte
    sessioni corpose rendeva anche la sostituzione di UN file lenta quanto salvarle tutte
    daccapo. Fa comunque un fallback sicuro al salvataggio completo se qualcosa nell'aggiornamento
    mirato non torna, così non lascia mai il foglio in uno stato incoerente.
    Restituisce un dict di tempi (in secondi) per ogni fase, utile per capire esattamente dove
    va il tempo quando l'operazione sembra lenta."""
    tempi = {}
    t_inizio_totale = time.time()

    aggiorna_stato_locale = None
    for s in lista_sessioni_completa:
        if s['id'] == id_sessione:
            aggiorna_stato_locale = s
            break
    if aggiorna_stato_locale is not None:
        aggiorna_stato_locale['pdf_bytes'] = nuovo_file_bytes

    t0 = time.time()
    # Backup locale SEMPRE aggiornato per primo, come in ogni altra funzione di salvataggio.
    try:
        with open(TRAINING_SESSIONS_FILE, 'wb') as _f_backup_preventivo:
            pickle.dump(lista_sessioni_completa, _f_backup_preventivo)
    except Exception:
        pass
    tempi['backup_locale'] = time.time() - t0

    if not _google_sheets_configurato():
        tempi['totale'] = time.time() - t_inizio_totale
        return tempi

    try:
        t0 = time.time()
        worksheet_pdf = _ottieni_worksheet_training_pdf()
        b64_nuovo = base64.b64encode(nuovo_file_bytes).decode('utf-8') if nuovo_file_bytes else ''
        righe_nuove = [[id_sessione, indice, b64_nuovo[inizio:inizio + DIMENSIONE_CHUNK_PDF]]
                       for indice, inizio in enumerate(range(0, len(b64_nuovo), DIMENSIONE_CHUNK_PDF))] if b64_nuovo else []
        for riga in righe_nuove:
            for cella in riga:
                if len(str(cella)) > 49000:
                    raise ValueError(f"A cell still exceeds Google Sheets' limit ({len(str(cella))} chars) even after chunking.")
        tempi['preparazione'] = time.time() - t0

        # Leggo SOLO la colonna degli ID (col_values), non l'intero foglio (get_all_values):
        # quest'ultima scaricherebbe anche tutti i chunk pesanti (fino a 40.000 caratteri
        # ciascuno) delle ALTRE sessioni solo per individuare le poche righe che mi servono —
        # è esattamente questo che rendeva l'operazione ancora lenta nonostante toccasse solo
        # una sessione: la lettura iniziale era comunque pesante quanto l'intero foglio.
        t0 = time.time()
        colonna_id_attuale = worksheet_pdf.col_values(1)
        tempi['lettura_id'] = time.time() - t0
        # Individuo le righe (1-based, +1 per l'intestazione) che appartengono a questo ID, per
        # toccare SOLO quelle — tutte le altre sessioni restano completamente intatte.
        indici_riga_da_sostituire = [i + 2 for i, id_riga in enumerate(colonna_id_attuale[1:]) if id_riga == id_sessione]

        t0 = time.time()
        if indici_riga_da_sostituire and indici_riga_da_sostituire == list(range(indici_riga_da_sostituire[0], indici_riga_da_sostituire[-1] + 1)):
            # Le righe esistenti di questa sessione sono contigue (il caso normale, dato che
            # vengono sempre scritte in blocco per lo stesso ID): cancello solo quel range.
            worksheet_pdf.delete_rows(indici_riga_da_sostituire[0], indici_riga_da_sostituire[-1])
        elif indici_riga_da_sostituire:
            # Caso raro/inatteso (righe non contigue): niente scorciatoie, torno al salvataggio
            # completo sicuro invece di rischiare di lasciare righe orfane in giro.
            salva_sessioni_allenamento_su_disco(lista_sessioni_completa)
            tempi['totale'] = time.time() - t_inizio_totale
            return tempi
        tempi['cancellazione_righe'] = time.time() - t0

        t0 = time.time()
        if righe_nuove:
            _scrivi_righe_a_blocchi(worksheet_pdf, righe_nuove, dimensione_blocco=40)
        tempi['scrittura_nuove_righe'] = time.time() - t0
    except Exception as e:
        st.sidebar.error(f"⚠️ Could not update this session's file on Google Sheets: {e}")
    tempi['totale'] = time.time() - t_inizio_totale
    return tempi

def salva_sessioni_allenamento_su_disco(lista_sessioni, permetti_svuotamento=False):
    # Backup locale SEMPRE scritto per primo, PRIMA di tentare Google Sheets — così un
    # salvataggio remoto interrotto a metà (rete, quota, qualunque motivo) non lascia MAI
    # l'app priva di una copia recente e recuperabile: è così che si sono persi i dati la
    # volta scorsa (il backup locale esisteva solo come fallback DOPO un errore, mai come
    # copia sistematica di ogni salvataggio riuscito).
    try:
        with open(TRAINING_SESSIONS_FILE, 'wb') as _f_backup_preventivo:
            pickle.dump(lista_sessioni, _f_backup_preventivo)
    except Exception:
        pass
    if _google_sheets_configurato():
        try:
            righe_meta = [[
                s['id'], s['nome_sessione'],
                json.dumps({'link_list': s['link_list'], 'note_generali': s['note_generali'],
                            'assegnazioni': s['assegnazioni'], 'gruppo': s.get('gruppo')})
            ] for s in lista_sessioni]

            righe_pdf = []
            for s in lista_sessioni:
                if not s.get('pdf_bytes'):
                    continue
                b64_completo = base64.b64encode(s['pdf_bytes']).decode('utf-8')
                for indice, inizio in enumerate(range(0, len(b64_completo), DIMENSIONE_CHUNK_PDF)):
                    righe_pdf.append([s['id'], indice, b64_completo[inizio:inizio + DIMENSIONE_CHUNK_PDF]])

            # Validazione PRIMA di cancellare ENTRAMBI i fogli: se qualche cella superasse
            # comunque il limite di Google Sheets, meglio fermarsi subito senza aver toccato
            # nulla, che cancellare e scoprirlo dopo — è già successo altrove in questa app.
            for riga in righe_meta + righe_pdf:
                for cella in riga:
                    if len(str(cella)) > 49000:
                        raise ValueError(f"A cell still exceeds Google Sheets' limit ({len(str(cella))} chars) even after chunking — aborting before touching either sheet.")

            worksheet_meta = _ottieni_worksheet_training_meta()
            # Protezione anti-svuotamento-accidentale su ENTRAMBI i fogli separatamente: prima
            # era applicata solo al foglio dei metadati, non a quello dei PDF — è esattamente
            # per questo che la volta scorsa i metadati sono stati azzerati mentre i PDF
            # (chunk ancora presenti) sono sopravvissuti, disallineati e non più raggiungibili
            # dal caricamento normale. permetti_svuotamento=True (solo da un reset esplicito)
            # bypassa entrambi i controlli.
            _blocca_se_svuotamento_sospetto(worksheet_meta, lista_sessioni, permetti_svuotamento, "training session(s)")
            worksheet_meta.clear()
            worksheet_meta.append_row(['id', 'nome_sessione', 'dati_json'])
            _scrivi_righe_a_blocchi(worksheet_meta, righe_meta)

            worksheet_pdf = _ottieni_worksheet_training_pdf()
            _blocca_se_svuotamento_sospetto(worksheet_pdf, righe_pdf, permetti_svuotamento, "training session PDF chunk(s)")
            worksheet_pdf.clear()
            worksheet_pdf.append_row(['id', 'indice_chunk', 'chunk_base64'])
            # Scritto A BLOCCHI PICCOLI (non tutto insieme): con molte sessioni corpose (es. 40
            # PDF scansionati) una singola chiamata enorme rischia di superare il limite di
            # dimensione per richiesta di Google Sheets e fallire SILENZIOSAMENTE — lasciando i
            # metadati delle sessioni salvati ma i PDF persi. Blocchi piccoli evitano il problema.
            _scrivi_righe_a_blocchi(worksheet_pdf, righe_pdf, dimensione_blocco=40)
            return
        except Exception as e:
            st.sidebar.error(f"⚠️ Could not save training sessions to Google Sheets: {e}")
            if not lista_sessioni:
                # Lista vuota e il salvataggio remoto è fallito (per il controllo di sicurezza
                # sopra, o per qualunque altro motivo): NON tocco nemmeno il backup locale, per
                # non rischiare di sovrascrivere un backup buono con una lista vuota sospetta.
                return
    with open(TRAINING_SESSIONS_FILE, 'wb') as f:
        pickle.dump(lista_sessioni, f)

# ============================================================
# LOGHI SQUADRA: magazzino condiviso in tutta l'app, indicizzato per nome squadra (esattamente
# come le foto giocatori sono indicizzate per identità). Non importa in quale sezione carichi il
# logo la prima volta (Training Sessions, Seasonal Report, Shooting Trend...): una volta agganciato
# a un nome, viene riconosciuto ovunque quel nome compaia, comprese le esportazioni PDF cumulative
# di squadra.
# ============================================================
TEAM_LOGOS_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "team_logos.pkl")

@st.cache_resource
def _ottieni_worksheet_loghi_squadra():
    import gspread
    from google.oauth2.service_account import Credentials
    credenziali = Credentials.from_service_account_info(
        dict(st.secrets['gcp_service_account']), scopes=GOOGLE_SHEETS_SCOPES
    )
    client = gspread.authorize(credenziali)
    foglio = client.open_by_key(st.secrets['season_sheet_id'])
    try:
        worksheet = foglio.worksheet('TeamLogos')
    except Exception:
        worksheet = foglio.add_worksheet(title='TeamLogos', rows=500, cols=2)
        worksheet.append_row(['squadra', 'logo_base64'])
    return _WorksheetConRetry(worksheet)

def carica_loghi_squadra_da_disco():
    if _google_sheets_configurato():
        try:
            worksheet = _ottieni_worksheet_loghi_squadra()
            valori = worksheet.get_all_values()
            return {r[0]: r[1] for r in valori[1:] if r and r[0] and len(r) > 1}
        except Exception:
            # Non arrendersi al primo errore: prova comunque il backup locale sotto
            # (se esiste) prima di restituire {} vuoto — meglio mostrare dati
            # un po' vecchi che nessun dato affatto.
            pass
    if os.path.exists(TEAM_LOGOS_FILE):
        try:
            with open(TEAM_LOGOS_FILE, 'rb') as f:
                return pickle.load(f)
        except Exception:
            return {}
    return {}

def salva_loghi_squadra_su_disco(loghi_dict, permetti_svuotamento=False):
    # Backup locale SEMPRE scritto per primo, PRIMA di tentare Google Sheets — così un
    # salvataggio remoto interrotto a metà (rete, quota, qualunque motivo) non lascia MAI
    # l'app priva di una copia recente e recuperabile: è così che si sono persi i dati la
    # volta scorsa (il backup locale esisteva solo come fallback DOPO un errore, mai come
    # copia sistematica di ogni salvataggio riuscito).
    try:
        with open(TEAM_LOGOS_FILE, 'wb') as _f_backup_preventivo:
            pickle.dump(loghi_dict, _f_backup_preventivo)
    except Exception:
        pass
    if _google_sheets_configurato():
        try:
            worksheet = _ottieni_worksheet_loghi_squadra()
            _blocca_se_svuotamento_sospetto(worksheet, loghi_dict, permetti_svuotamento, "team logo(s)")
            worksheet.clear()
            worksheet.append_row(['squadra', 'logo_base64'])
            righe = [[nome, logo] for nome, logo in loghi_dict.items()]
            if righe:
                worksheet.append_rows(righe)
            return
        except Exception as e:
            st.sidebar.error(f"⚠️ Could not save team logos to Google Sheets: {e}")
            if not loghi_dict:
                # Dati vuoti e salvataggio remoto fallito: NON tocco il backup locale,
                # per non rischiare di sovrascrivere un backup buono con dati vuoti.
                return
    with open(TEAM_LOGOS_FILE, 'wb') as f:
        pickle.dump(loghi_dict, f)

def gestisci_logo_squadra(nome_squadra, key_prefix):
    """Widget riusabile: mostra il logo attuale della squadra (se presente) e un uploader per
    caricarne/sostituirne uno. Riconosciuto ovunque nell'app in base al nome squadra."""
    chiave_sicura = _chiave_css_sicura(nome_squadra)
    key_uploader = f"{key_prefix}_logo_{chiave_sicura}"
    key_marcatore = f"_processato_{key_uploader}"
    col_logo, col_upload = st.columns([1, 4])
    with col_upload:
        nuovo_file = st.file_uploader(f"Logo for {nome_squadra} (optional, jpg/png)", type=['jpg', 'jpeg', 'png'],
                                       key=key_uploader, label_visibility="collapsed")
        if nuovo_file is not None:
            marcatore_attuale = f"{nuovo_file.name}-{nuovo_file.size}"
            if st.session_state.get(key_marcatore) != marcatore_attuale:
                st.session_state['loghi_squadre'][nome_squadra] = elabora_foto_giocatore(nuovo_file)
                salva_loghi_squadra_su_disco(st.session_state['loghi_squadre'])
                st.session_state[key_marcatore] = marcatore_attuale
                st.rerun()
    with col_logo:
        logo_b64 = st.session_state['loghi_squadre'].get(nome_squadra)
        if logo_b64:
            st.image(foto_base64_a_bytes(logo_b64), width=80)
            if st.button("🗑️", key=f"rimuovi_{key_uploader}", help="Remove team logo"):
                del st.session_state['loghi_squadre'][nome_squadra]
                salva_loghi_squadra_su_disco(st.session_state['loghi_squadre'])
                st.rerun()

